    stderr(`dsh-plugin-preflight: ${args.error}\n\n${USAGE}`);
    return 2;
  }
  if (args.help) { stdout(USAGE); return 0; }
  if (args.version) { stdout(`${version}\n`); return 0; }

  let report;
  try {
    report = await check(args.dir === null ? {} : { dir: args.dir });
