    const lines = renderReport(report);
    stdout(`${(isTty ? colorize(lines) : lines).join('\n')}\n`);
  }

  const blocked = report.summary.errors > 0 || (args.strict && report.summary.warnings > 0);
  return blocked ? 1 : 0;
}

